label:has(input:checked)~label>span:first-of-type{color:#e4476b}.review-rating-options input:focus-visible+span{outline:2px solid var(--accent);outline-offset:2px;border-radius:3px}.review-form-footer{display:flex;align-items:center;gap:14px;flex-wrap:wrap}.review-submit{font-weight:400}.review-feedback{margin:0;color:#26704e}.review-feedback.is-error{color:#a34747}.review-sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}@media(max-width:650px){.review-form{padding:16px}.review-item{padding:14px}.review-item-head{gap:10px}}
